 for l in selected:w.writerow([datetime.datetime.fromtimestamp(l['kickoff']/1000,ZoneInfo('Europe/Lisbon')).isoformat(),l['home']+' - '+l['away'],labels.get(l['market'],l['market']),l['odd'],t['book'],t['odd'],'por apurar'])
